label("B", B, NE);
label("C", C, SE);
label("D", D, SW);
label("E", E, SW);
label("F", F, NW);
label("O", O, dir(0));
label("M", M, NE);
label("$r$", (F+O)/2, NE);
label("$r$", (E+O)/2, SE);
label("$r$", M, W);
